const std = @import("std");
pub const blocked_patterns = [_][]const u8{"password=", "api_key", "secret_key", "private key", "token=", "ssn"};
pub const replacement = "[REMOVED]";
pub fn normalize_payload(allocator: std.mem.Allocator, payload: []const u8) ![]u8 { var text = try std.mem.replaceOwned(u8, allocator, payload, "\x00", ""); return std.mem.replaceOwned(u8, allocator, text, "\r\n", "\n"); }
pub fn remove_blocked_patterns(allocator: std.mem.Allocator, normalized_payload: []const u8) ![]u8 { var cleaned_payload = try allocator.dupe(u8, normalized_payload); for (blocked_patterns) |blocked_pattern| { const next = try std.mem.replaceOwned(u8, allocator, cleaned_payload, blocked_pattern, replacement); cleaned_payload = next; } return cleaned_payload; }
pub fn escape_output(allocator: std.mem.Allocator, cleaned_payload: []const u8) ![]u8 { var output = try std.mem.replaceOwned(u8, allocator, cleaned_payload, "&", "&amp;"); output = try std.mem.replaceOwned(u8, allocator, output, "<", "&lt;"); output = try std.mem.replaceOwned(u8, allocator, output, ">", "&gt;"); output = try std.mem.replaceOwned(u8, allocator, output, "\"", "&quot;"); output = try std.mem.replaceOwned(u8, allocator, output, "'", "&#39;"); return std.mem.replaceOwned(u8, allocator, output, "`", "&#96;"); }
pub fn clean(allocator: std.mem.Allocator, threat: []const u8, payload: []const u8) ![]u8 { _ = threat; const normalized_payload = try normalize_payload(allocator, payload); const cleaned_payload = try remove_blocked_patterns(allocator, normalized_payload); return escape_output(allocator, cleaned_payload); }
pub const LLM_1ntruder = struct { pub fn clean(allocator: std.mem.Allocator, threat: []const u8, payload: []const u8) ![]u8 { return @import("lib.zig").clean(allocator, threat, payload); } };
